 function rs(){var a=document.querySelectorAll('svg[data-d1]');for(var i=0;i<a.length;i++){a[i].querySelector('.c1').textContent=a[i].dataset.d1;a[i].querySelector('.c2').textContent=a[i].dataset.d2}}
